56	/**
57	 * Computes a stable lookup key for an SDK message.
58	 * Non-system messages use `type`; system messages use `type:subtype`.
59	 */
60	export function messageKey(message: SDKMessage): string {
61		if (message.type === 'system') {
62			return `system:${message.subtype}`;
63		}
64		return message.type;
65	}
