49	export class TelemetryUserConfigImpl implements ITelemetryUserConfig {
50		declare readonly _serviceBrand: undefined;
51		// tracking id from auth token
52		public trackingId: string | undefined;
53		public organizationsList: string | undefined;
54		public enterpriseList: string | undefined;
55		public optedIn: boolean;
56	
57		constructor(
58			trackingId: string | undefined,
59			optedIn: boolean | undefined,
60			@ICopilotTokenStore private readonly _tokenStore: ICopilotTokenStore,
61		) {
62			this.trackingId = trackingId;
63			this.optedIn = optedIn ?? false;
64			this.updateFromToken(this._tokenStore.copilotToken);
65			this._tokenStore.onDidStoreUpdate(() => {
66				this.updateFromToken(this._tokenStore.copilotToken);
67			});
68		}
69	
70		private updateFromToken(token: CopilotToken | undefined) {
71			if (!token) {
72				return;
73			}
74			const enhancedTelemetry = token.getTokenValue('rt') === '1';
75			const trackingId = token.getTokenValue('tid');
76			if (trackingId !== undefined) {
77				this.trackingId = trackingId;
78				this.organizationsList = token.organizationList.toString();
79				this.enterpriseList = token.enterpriseList.toString();
80				this.optedIn = enhancedTelemetry;
81			}
82		}
83	}
