89	/**
90	 * Creates a getter that returns the tracking ID from the token store.
91	 * The cache is:
92	 * - initialized from the current token (if available) when the getter is created
93	 * - updated whenever the token store changes
94	 * - returned even when the token is temporarily unavailable
95	 */
96	export function createTrackingIdGetter(tokenStore: ICopilotTokenStore): () => string | undefined {
97		let cachedTrackingId = tokenStore.copilotToken?.getTokenValue('tid');
98		tokenStore.onDidStoreUpdate(() => {
99			const trackingId = tokenStore.copilotToken?.getTokenValue('tid');
100			if (trackingId) {
101				cachedTrackingId = trackingId;
102			}
103		});
104		return () => cachedTrackingId;
105	}
