598		private async _processMessages(): Promise<void> {
599			const otelToolSpans = new Map<string, ISpanHandle>();
600			const otelHookSpans = new Map<string, ISpanHandle>();
601			const subagentTraceContexts = new Map<string, TraceContext>();
602			try {
603				const unprocessedToolCalls = new Map<string, Anthropic.Beta.Messages.BetaToolUseBlock>();
604				for await (const message of this._queryGenerator!) {
605					// Mark session as resumed after first SDK message confirms session exists on disk.
606					// This ensures future restarts (yield, settings change) use `resume` instead of `sessionId`.
607					if (message.session_id && !this._isResumed) {
608						this._isResumed = true;
609					}
610	
611					// Skip if no current request (e.g., after yield cleared it)
612					if (!this._currentRequest) {
613						this.logService.trace('[ClaudeCodeSession] Skipping message - no current request');
614						continue;
615					}
616	
617					const currentRequest = this._currentRequest;
618	
619					// Check if current request was cancelled
620					if (currentRequest.token.isCancellationRequested) {
621						throw new Error('Request was cancelled');
622					}
623	
624					// Track OTel metrics from SDK messages
625					this._otelTracker.onMessage(message, subagentTraceContexts);
626	
627					this.logService.trace(`claude-agent-sdk Message: ${JSON.stringify(message, null, 2)}`);
628	
629					let result;
630					try {
631						result = this.instantiationService.invokeFunction(dispatchMessage, message, this.sessionId, {
632							stream: currentRequest.stream,
633							toolInvocationToken: currentRequest.request.toolInvocationToken,
634							editTracker: this._editTracker,
635							token: currentRequest.token,
636						}, {
637							unprocessedToolCalls,
638							otelToolSpans,
639							otelHookSpans,
640							parentTraceContext: this._otelTracker.traceContext,
641							subagentTraceContexts,
642						});
643					} catch (dispatchError) {
644						this.logService.warn(`[ClaudeCodeSession] Failed to dispatch message (stream may be disposed after yield): ${dispatchError}`);
645					}
646	
647					if (currentRequest.yieldRequested?.()) {
648						this.logService.trace('[ClaudeCodeSession] Yield requested - signaling session completion so next request can start');
649	
650						// Complete the current request gracefully but don't kill the session
651						if (!currentRequest.deferred.isSettled) {
652							await currentRequest.deferred.complete();
653						}
654					}
655	
656					if (result?.requestComplete) {
657						// End the invoke_agent span for this request
658						this._otelTracker.endRequest();
659						// Clear the capturing token so subsequent requests get their own
660						this.sessionStateService.setCapturingTokenForSession(this.sessionId, undefined);
661						const completed = this._inFlightRequests.shift();
662						if (completed && !completed.deferred.isSettled) {
663							await completed.deferred.complete();
